* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 32px 16px;

    font-family: Arial, "Segoe UI", sans-serif;
    background: #eceff1;
    display: flex;
    justify-content: center;
}

.khung-km {
    width: min(860px, 100%);
    background: #ffffff;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);
    border-radius: 4px;
    overflow: hidden;
}

header {
    background: #C8102E;
    color: #ffffff;
    text-align: center;
    padding: 14px;
}

header h1 {
    margin: 0;
    font-size: 22px;
}

.dai-phu {
    background: #FBE3E8;
    color: #C8102E;
    text-align: center;
    font-weight: 700;
    padding: 7px;
    letter-spacing: 0.5px;
}

.than-bai {
    display: grid;
    grid-template-columns: 1fr 1px 1fr;

    gap: 22px;
    padding: 22px;
}

.than-bai::before {
    content: "";
    background: #e0e0e0;
    grid-column: 2;
    grid-row: 1;
}

.anh-sp {
    float: right;
    width: 180px;
    margin: 0 0 10px 16px;
}

h3 {
    color: #C8102E;
    font-size: 15px;
    margin: 0 0 8px;
}

ul {
    margin: 0 0 16px;
    padding-left: 18px;
    font-size: 14px;
    line-height: 1.65;
    color: #333333;
}

@media (max-width: 680px) {
    .than-bai {
        grid-template-columns: 1fr;
    }
    .than-bai::before {
        display: none;
    }

}
